// Inline SVG icons for the AI Video editing surface. Dependency-free: every
// glyph is a path on a 24px grid tinted with currentColor, so the button or
// chip that hosts it decides the ink. Keep the same string-concat style as the
// rest of renderer/js.

import { HARNESS_LOGOS } from "./harness-logos.js";

function svg(inner, size, cls, viewBox) {
  return (
    '<svg class="' +
    (cls || "ai-ic") +
    '" width="' +
    size +
    '" height="' +
    size +
    '" viewBox="' +
    (viewBox || "0 0 24 24") +
    '" aria-hidden="true" focusable="false">' +
    inner +
    "</svg>"
  );
}

function stroke(d, w) {
  return (
    '<path fill="none" stroke="currentColor" stroke-width="' +
    (w || 1.7) +
    '" stroke-linecap="round" stroke-linejoin="round" d="' +
    d +
    '"/>'
  );
}

function fill(d, color) {
  return '<path fill="' + (color || "currentColor") + '" d="' + d + '"/>';
}

