// Media kinds used by library items and the pin picker.
const KIND_GLYPHS = {
  video: "film",
  image: "image",
  audio: "audio",
  card: "card",
};

export function kindIcon(kind, size) {
  const name = Object.hasOwn(KIND_GLYPHS, kind) ? KIND_GLYPHS[kind] : "file";
  return svg(GLYPHS[name], size || 16);
}

export function icon(name, size, cls) {
  const body = Object.hasOwn(GLYPHS, name) ? GLYPHS[name] : GLYPHS.file;
  return svg(body, size || 16, cls);
}

