const HARNESS_GLYPHS = {
  agent:
    '<rect x="3.5" y="4.5" width="17" height="15" rx="2.4" fill="none" stroke="currentColor" stroke-width="1.7"/>' +
    stroke("m7.6 9.6 2.7 2.4-2.7 2.4M12.4 15h4.2"),
};

// Names people and adapters use for agents whose registry id differs.
const LOGO_ALIASES = {
  droid: "factory-droid",
  factory: "factory-droid",
  pi: "pi-acp",
  amp: "amp-acp",
  augment: "auggie",
  grok: "grok-build",
  qwen: "qwen-code",
  mistral: "mistral-vibe",
  vibe: "mistral-vibe",
  antigravity: "antigravity-acp",
  glm: "glm-acp-agent",
  minimax: "minimax-code",
  codebuddy: "codebuddy-code",
};

function logoBase(id) {
  return id.replace(/-(acp|cli|code|agent)$/g, "").replace(/-(acp|cli|code|agent)$/g, "");
}

// The agent's own logo from the ACP Registry (harness-logos.js), matched by
// id, alias, or the id without its -acp/-cli suffix.
function registryLogo(key) {
  if (Object.hasOwn(HARNESS_LOGOS, key)) return HARNESS_LOGOS[key];
  if (Object.hasOwn(HARNESS_LOGOS, key + "-acp")) return HARNESS_LOGOS[key + "-acp"];
  const base = logoBase(key);
  for (const [alias, target] of Object.entries(LOGO_ALIASES)) if (base === alias || base.split(/[-_ ]/).includes(alias)) return HARNESS_LOGOS[target];
  for (const id of Object.keys(HARNESS_LOGOS)) if (logoBase(id) === base) return HARNESS_LOGOS[id];
  return null;
}

export function harnessIcon(id, size) {
  const key = String(id || "").toLowerCase();
  const px = size || 15;
  if (!Object.hasOwn(HARNESS_BRANDS, key)) {
    const exact = Object.hasOwn(HARNESS_LOGOS, key) ? HARNESS_LOGOS[key] : null;
    if (exact) return svg(exact.body, px, "ai-ic ai-harness-ic ai-harness-logo", exact.viewBox);
  }
  const brandName = Object.hasOwn(HARNESS_BRANDS, key)
    ? key
    : key.includes("cursor")
      ? "cursor"
      : key.includes("devin")
        ? "devin"
        : key.includes("claude")
          ? "claude"
          : key.includes("codex") || key.includes("openai")
            ? "codex"
            : key.includes("gemini")
              ? "gemini"
              : key.includes("copilot")
                ? "copilot"
                : key.includes("kimi")
                  ? "kimi"
                  : key.includes("opencode")
                    ? "opencode"
                    : "";
  if (brandName) {
    const brand = HARNESS_BRANDS[brandName];
    return svg(brand.body, px, "ai-ic ai-harness-ic ai-harness-brand-" + brandName, brand.viewBox);
  }
  const logo = registryLogo(key);
  if (logo) return svg(logo.body, px, "ai-ic ai-harness-ic ai-harness-logo", logo.viewBox);
  const name = Object.hasOwn(HARNESS_GLYPHS, key) ? key : "agent";
  return svg(HARNESS_GLYPHS[name], px, "ai-ic ai-harness-ic");
}
